const msg = $json.message || $json;
const d = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = `${d.getUTCFullYear()}${pad(d.getUTCMonth()+1)}${pad(d.getUTCDate())}-${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}`;
const text = (msg.text || msg.caption || '').trim();
const hasPhoto = Array.isArray(msg.photo) && msg.photo.length > 0;
const messageId = msg.message_id;
const chatId = msg.chat ? msg.chat.id : null;
const mediaGroupId = msg.media_group_id || null;
const isAlbum = Boolean(mediaGroupId);
const safeGroup = String(mediaGroupId || '').replace(/[^a-zA-Z0-9_-]/g, '_');
const safeChat = String(chatId || 'chat').replace(/[^a-zA-Z0-9_-]/g, '_');
const folderName = isAlbum ? `album_${safeChat}_${safeGroup}` : `${stamp}_msg${messageId}`;
const photoFileName = `photo_${messageId}.jpg`;
const binIn = $input.item.binary || {};
const firstKey = Object.keys(binIn)[0];
let binaryOut = {};
if (hasPhoto && firstKey) { binaryOut = { data: binIn[firstKey] }; }
return {
  json: {
    folder_name: folderName,
    brief_id: folderName,
    created_at: d.toISOString(),
    text,
    has_photo: hasPhoto,
    photo_filename: photoFileName,
    is_album: isAlbum,
    album_key: isAlbum ? `${safeChat}:${safeGroup}` : null,
    album_quiet_window_sec: 8,
    telegram: {
      chat_id: chatId,
      message_id: messageId,
      media_group_id: mediaGroupId,
      user_id: msg.from ? msg.from.id : null,
      username: msg.from ? (msg.from.username || null) : null,
      first_name: msg.from ? (msg.from.first_name || null) : null
    }
  },
  binary: binaryOut
};

const n = $('Normalisation').item.json;
const files = Array.isArray($json.files) ? $json.files : [];
const folder = files[0] || {};
if (!folder.id) throw new Error(`Drive folder search returned no folder for ${n.folder_name}`);
return {
  json: {
    ...n,
    folder_id: folder.id,
    folder_url: folder.webViewLink || `https://drive.google.com/drive/folders/${folder.id}`,
    folder_was_created: false
  }
};

const n = $('Normalisation').item.json;
const folder = $json || {};
if (!folder.id) throw new Error(`Drive folder creation returned no id for ${n.folder_name}`);
return {
  json: {
    ...n,
    folder_id: folder.id,
    folder_url: folder.webViewLink || `https://drive.google.com/drive/folders/${folder.id}`,
    folder_was_created: true
  }
};

const norm = $('Normalisation').item;
return {
  json: {
    ...$json,
    folder_id: $json.folder_id,
    photo_filename: norm.json.photo_filename
  },
  binary: norm.binary
};

const n = $('Prep upload photo').item.json;
const uploaded = $json || {};
const photo = {
  filename: n.photo_filename,
  drive_file_id: uploaded.id || null,
  mime: uploaded.mimeType || 'image/jpeg',
  telegram_message_id: n.telegram ? n.telegram.message_id : null
};
const out = {
  ...n,
  photos: [photo],
  folder_url: n.folder_url || `https://drive.google.com/drive/folders/${n.folder_id}`
};
if (n.is_album) {
  const data = $getWorkflowStaticData('global');
  data.telegram_album_buffer = data.telegram_album_buffer || {};
  const key = n.album_key;
  const existing = data.telegram_album_buffer[key] || {};
  const photos = existing.photos || {};
  photos[String(photo.telegram_message_id || n.photo_filename)] = photo;
  const token = `${n.telegram.message_id}-${Date.now()}`;
  data.telegram_album_buffer[key] = {
    brief_id: existing.brief_id || n.brief_id,
    created_at: existing.created_at || n.created_at,
    folder_id: existing.folder_id || n.folder_id,
    folder_name: existing.folder_name || n.folder_name,
    folder_url: existing.folder_url || out.folder_url,
    text: existing.text || n.text || '',
    telegram: existing.telegram || n.telegram,
    photos,
    latest_token: token,
    last_seen_at: new Date().toISOString()
  };
  out.album_token = token;
}
return { json: out };

const current = $input.first().json || {};
if (!current.is_album || !current.album_key || !current.album_token) return [];
const data = $getWorkflowStaticData('global');
const buffer = data.telegram_album_buffer || {};
const album = buffer[current.album_key];
if (!album || album.latest_token !== current.album_token) return [];
const photos = Object.values(album.photos || {}).sort((a, b) => (a.telegram_message_id || 0) - (b.telegram_message_id || 0));
delete buffer[current.album_key];
data.telegram_album_buffer = buffer;
return [{
  json: {
    brief_id: album.brief_id,
    created_at: album.created_at,
    text: album.text || '',
    photos,
    folder_id: album.folder_id,
    folder_name: album.folder_name,
    folder_url: album.folder_url || `https://drive.google.com/drive/folders/${album.folder_id}`,
    telegram: album.telegram,
    album_finalized: true
  }
}];

const j = $json || {};
return {
  json: {
    brief_id: j.brief_id,
    created_at: j.created_at,
    text: j.text || '',
    photos: Array.isArray(j.photos) ? j.photos : [],
    folder_id: j.folder_id,
    folder_name: j.folder_name,
    folder_url: j.folder_url || (j.folder_id ? `https://drive.google.com/drive/folders/${j.folder_id}` : null),
    telegram: j.telegram
  }
};

const c = $json || {};
const folderUrl = c.folder_url || (c.folder_id ? `https://drive.google.com/drive/folders/${c.folder_id}` : null);
const brief = {
  brief_id: c.brief_id,
  created_at: c.created_at,
  source: 'telegram',
  status: 'pending',
  text: c.text || '',
  photos: Array.isArray(c.photos) ? c.photos : [],
  drive: { folder_id: c.folder_id, folder_name: c.folder_name, folder_url: folderUrl },
  telegram: c.telegram || {},
  siga: { action: null, items: [], processed_at: null, notes: null }
};
const content = JSON.stringify(brief, null, 2);
const b64 = Buffer.from(content, 'utf8').toString('base64');
return { json: brief, binary: { data: { data: b64, mimeType: 'application/json', fileName: 'brief.json' } } };

